// Replay ONE dead-letter item, retrying with exponential backoff + full jitter.
// Wait before retry n = random number between 0 and min(30s, 1s * 2^n).
const dl = $('One at a time').item.json;
const p = dl.payload || {};
const MAX_TRIES = 4, BASE_MS = 1000, CAP_MS = 30000;
const sleep = ms => new Promise(r => setTimeout(r, ms));
const backoff = n => Math.floor(Math.random() * Math.min(CAP_MS, BASE_MS * 2 ** n));

// Same strict matching rule as Part 2 (high = domain spells the company name)
function pickDomain(list, name) {
  const base = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
  const clean = s => base(s).replace(/\(.*\)/g, '')
    .replace(/\b(inc|llc|ltd|limited|gmbh|corp|corporation|co|plc|sa|ag|bv|group|holdings|technologies|technology|labs|hq|the|an|a)\b/g, '')
    .replace(/[^a-z0-9]/g, '');
  const SUFFIX = /(hq|app|ai|io|grp|group|inc|global|team|labs|software|tech)$/;
  const want = clean(name);
  const pick = list.find(s => clean(s.name) === want);
  if (!pick) return { domain: null, domain_confidence: null };
  const domain = String(pick.domain).toLowerCase().replace(/^www\./, '');
  const d = domain.split('.')[0].replace(/[^a-z0-9]/g, '');
  const dc = d.replace(/^(go|get|try|use|join|hey|my)/, '').replace(SUFFIX, '');
  const nc = want.replace(SUFFIX, '');
  return { domain, domain_confidence: (d === want || dc === nc || d === nc || dc === want) ? 'high' : 'review' };
}

// A row that failed while SAVING already has its data: just hand it back to be saved again.
if (dl.provider === 'supabase') {
  return { json: { dl_id: dl.id, provider: dl.provider, ok: true, err: null, tries: 0, row_data: p } };
}

let lastErr = null, tries = 0;
for (let n = 0; n < MAX_TRIES; n++) {
  tries++;
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET', json: true, timeout: 15000,
      url: 'https://autocomplete.clearbit.com/v1/companies/suggest?query=' + encodeURIComponent(p.company_name || ''),
    });
    const m = pickDomain(Array.isArray(res) ? res : [], p.company_name);
    return { json: { dl_id: dl.id, provider: dl.provider, ok: true, err: null, tries,
      row_data: { company_key: p.company_key, company_name: p.company_name, company_slug: p.company_slug,
                  domain: m.domain, domain_confidence: m.domain_confidence,
                  enrich_error: m.domain ? null : 'No confident name match (replay)' } } };
  } catch (e) {
    lastErr = String(e.message || e).slice(0, 300);
    const status = e.httpCode || e.statusCode || (e.response && e.response.status);
    if (status && Number(status) >= 400 && Number(status) < 500 && Number(status) !== 429) break; // our request is wrong: retrying won't help
    if (n < MAX_TRIES - 1) await sleep(backoff(n));
  }
}
return { json: { dl_id: dl.id, provider: dl.provider, ok: false, err: lastErr, tries, row_data: null } };

const r = $('Save replay result').all().map(i => String(i.json.data || '').replace(/"/g, ''));
const skipped = $('Breaker allows call?').all().length - $('Retry with backoff + jitter').all().length;
const count = s => r.filter(x => x === s).length;
return [{ json: { replayed: r.length, resolved: count('resolved'), retrying_later: count('retrying'),
  gave_up: count('gave_up'), not_replayable: count('not_replayable'), skipped_breaker_open: Math.max(skipped, 0) } }];
